  $$$TRACE("Inside Update Method")
	//quit $$$OK

  d ..Adapter.SetAutoCommit(0)

  #dim tSC As %Status=$$$OK
  Set pResponse=##class(Ens.StringContainer).%New()
  set pResponse.StringValue="No Of Rows affected"
  set advProvider=pRequest.ADVPROVIDER
  Set prvdrRequest=##class(Ens.StringContainer).%New()
  set prvdrRequest.StringValue=pRequest.ADVPROVIDER.PRVDRID
  try {
	set tSc = ..AddOrUpdate(prvdrRequest, .response)
	if ('$ISOBJECT(response)||(response.RowCount=0)){
		set tSC=..AddADVPROVIDER(prvdrRequest,.pResponse)
	}
	If $$$ISOK(tSC){
		set tSC=..UpdateADVPROVIDER(advProvider,.pResponse)
	}
	If $$$ISOK(tSC){
		set tSC=..UpdateADVPROVIDERADDRESS(pRequest,.pResponse)
	}
	If $$$ISOK(tSC){
		set tSC=..UpdateADVPROVIDERSPECIALITY(pRequest,.pResponse)
	}
	If $$$ISOK(tSC){
		set tSC=..UpdateFACILITYAFFILIATION(pRequest,.pResponse)
	}
	If $$$ISOK(tSC){
		set tSC=..UpdateAdvProviderEducation(pRequest,.pResponse)
	}
	If $$$ISOK(tSC){
		set tSC=..UpdateProviderBoard(pRequest,.pResponse)
	}
	If $$$ISOK(tSC){
		set tSC=..UpdatePrvdrLicense(pRequest,.pResponse)
	}
  } 
  Catch eException {
       $$$TRACE("Inside Catch")
 	   set errTxt = $System.Status.GetErrorText(%objlasterror)
       $$$LOGERROR("Exception when update Corpprv DB: " _errTxt _ ", Excp:" _ eException.Name _ " " _ eException.Code _ " " _ eException.Location_" for provider: "_prvdrRequest.StringValue)
       $$$LOGERROR($ZERROR)
  }
  If $$$ISOK(tSC){
		d ..Adapter.Commit()  
  }Else{
		d ..Adapter.Rollback() 
  }	

	Quit tSC

